import { ProductIdSchema, type ProductId } from "./catalog.ts";

/**
 * Account-wide achievements and referrals.
 *
 * Authority lives in the provider ledger (Convex). The public ATProto record
 * written to the account's PDS is a portable display copy only: the account
 * owner can edit it, so nothing may infer an award or a reward from it.
 */

export const ACHIEVEMENT_COLLECTION = "info.notorganic.achievement";
/** Granular ATProto OAuth permissions needed to publish an achievement record. */
export const ACHIEVEMENT_PUBLISH_SCOPES = [
  `repo:${ACHIEVEMENT_COLLECTION}`,
  "blob:image/png",
