              <div class="min-w-0">
                <p
                  class="text-sm text-[var(--color-ink)]"
                  style={{ fontFamily: "var(--font-display)" }}
                >
                  {award.title}
                </p>
                <p class="mt-0.5 text-xs text-[var(--color-ink-light)]">
