/**
 * Achievement and referral issuance.
 *
 * Every write is made by a product's server: the access token must be a
 * service token minted from that product's signed assertion. The DID is the
 * token subject and the issuing application is the token product; neither is
 * read from the request body, so a browser cannot name another account or
 * claim a reward from a click.
 */

export interface AchievementStore {
  award(input: { did: string; issuer: ProductId; key: string }): Promise<{ award: AchievementAward; replay: boolean }>;
  list(input: { did: string }): Promise<{ object: "list"; data: AchievementAward[] }>;
  claimReferral(input: { did: string; caller: ProductId; code: string }): Promise<{ claim: ReferralClaim; replay: boolean }>;
  qualifyReferral(input: { did: string; caller: ProductId; event: string }): Promise<{ claim: ReferralClaim; replay: boolean }>;
}

const ERRORS: Record<string, [number, string, string]> = {
  ACHIEVEMENT_NOT_FOUND: [404, "not_found_error", "That achievement is not defined for this application."],
  ACHIEVEMENT_APPLICATION_MISMATCH: [403, "permission_error", "An application can only issue its own achievements."],
  APPLICATION_MEMBERSHIP_INACTIVE: [403, "permission_error", "This account is not active for the application."],
  APPLICATION_MEMBERSHIP_UNVERIFIED: [403, "permission_error", "This account has not joined the referral's application yet."],
  APPLICATION_UNKNOWN: [403, "permission_error", "The issuing application is not recognised."],
  REFERRAL_CODE_INVALID: [404, "not_found_error", "That referral code is not valid."],
  REFERRAL_APPLICATION_MISMATCH: [403, "permission_error", "This application cannot record claims for that referral code."],
  REFERRAL_SELF: [409, "invalid_request_error", "An account cannot refer itself."],
  REFERRAL_ALREADY_CLAIMED: [409, "invalid_request_error", "This account already has a referral for the application."],
  REFERRAL_EXISTING_MEMBER: [409, "invalid_request_error", "This account joined the application before the referral."],
  REFERRAL_NOT_FOUND: [404, "not_found_error", "This account has no referral for the application."],
  REFERRAL_CODE_REVOKED: [409, "invalid_request_error", "The referral code was revoked before the referral qualified."],
  REFERRAL_REFERRER_INACTIVE: [409, "invalid_request_error", "The referring account is no longer active, so no reward is paid."],
  REFERRAL_POLICY_MISSING: [409, "invalid_request_error", "Referral qualification is not configured for this application."],
  REFERRAL_EVENT_NOT_QUALIFYING: [409, "invalid_request_error", "That event does not qualify a referral."],
};

function convexCode(error: unknown): string {
  if (error instanceof ConvexError && typeof error.data === "string") return error.data;
  const message = error instanceof Error ? error.message : "";
  return message.match(/(?:^|Error:\s*|ConvexError:\s*)([A-Z][A-Z0-9_]+)(?:\s|$)/u)?.[1] ?? "";
}

function gatewayError(error: unknown): never {
  const code = convexCode(error);
  const known = ERRORS[code];
  if (known) throw new GatewayError(known[0], known[1], known[2], code.toLowerCase());
  throw error;
}

export class ConvexAchievementStore implements AchievementStore {
  private readonly convex: Pick<ConvexHttpClient, "query" | "mutation">;
  constructor(private readonly config: { convexUrl: string; gatewaySecret: string; convexClient?: Pick<ConvexHttpClient, "query" | "mutation"> }) {
    this.convex = config.convexClient ?? new ConvexHttpClient(config.convexUrl);
  }
  private get secret() { return { serviceSecret: this.config.gatewaySecret }; }
  async award(input: { did: string; issuer: ProductId; key: string }) {
    return (await this.convex.mutation(makeFunctionReference<"mutation">("REDACTED"), { ...this.secret, ...input }).catch(gatewayError)) as { award: AchievementAward; replay: boolean };
  }
  async list(input: { did: string }) {
    return (await this.convex.query(makeFunctionReference<"query">("achievements:listForGateway"), { ...this.secret, ...input })) as { object: "list"; data: AchievementAward[] };
  }
  async claimReferral(input: { did: string; caller: ProductId; code: string }) {
    return (await this.convex.mutation(makeFunctionReference<"mutation">("referrals:claim"), { ...this.secret, ...input }).catch(gatewayError)) as { claim: ReferralClaim; replay: boolean };
  }
  async qualifyReferral(input: { did: string; caller: ProductId; event: string }) {
    return (await this.convex.mutation(makeFunctionReference<"mutation">("referrals:qualify"), { ...this.secret, ...input }).catch(gatewayError)) as { claim: ReferralClaim; replay: boolean };
  }
}

function requireServer(principal: VerifiedPrincipal): void {
  if (principal.tokenType !== "service" || (principal.environment !== undefined && principal.environment !== "server")) {
    throw new GatewayError(403, "permission_error", "Only an application's server can issue achievements or referral claims.", "server_token_required");
  }
}

async function body(request: Request): Promise<unknown> {
  return request.json().catch(() => null);
}

export function registerAchievementGateway(
  app: Hono<{ Variables: { principal: VerifiedPrincipal } }>,
  tokens: TokenService,
  store?: AchievementStore,
) {
  const available = (): AchievementStore => {
    if (!store) throw new GatewayError(503, "api_error", "Achievements are not available on this server.", "achievements_unavailable");
    return store;
  };
  for (const path of ["/v1/achievements/*", "/v1/referrals/*"]) {
    app.use(path, bodyLimit({ maxSize: 4096 }));
    app.use(path, async (c, next) => { c.header("Cache-Control", "no-store"); await next(); });
  }

  app.post("/v1/achievements/awards", async (c) => {
    const principal = await tokens.authenticate(c.req.raw, "REDACTED");
    requireServer(principal);
    const input = AchievementAwardInputSchema.safeParse(await body(c.req.raw));
    if (!input.success) throw new GatewayError(400, "invalid_request_error", "Supply an achievement key.", "invalid_achievement", "achievement");
    const result = await available().award({ did: principal.accountId, issuer: principal.product, key: input.data.achievement });
    c.header("x-notorganic-idempotent-replay", String(result.replay));
    return c.json(result.award, result.replay ? 200 : 201);
  });

