import { queryGeneric } from "convex/server";
import { v } from "convex/values";
import { requireGatewaySecret, requirePortalSecret } from "./lib";
import { financeAuthority, canonical, financeDigest } from "./unisonFinance";
import { accountDeleted } from "./accountDeletion";
import { ReferralCodeSchema } from "@notorganic/contracts";
const auth = (secret: string, role: string) => role === "gateway" ? requireGatewaySecret(secret) : requirePortalSecret(secret);
const args = { serviceSecret: v.string(), role: v.union(v.literal("gateway"), v.literal("portal")) };
/** Private routing hints only. The caller migrates this owner, then reads the
 * authoritative native record; these source rows never decide publication. */
export const awardContext = queryGeneric({ args: { ...args, id: v.string() }, handler: async (ctx, input) => {
  auth(input.serviceSecret, input.role);
  const id = ctx.db.normalizeId("achievementAwards", input.id);
  const row = id ? await ctx.db.get(id) : null;
  return row && !await accountDeleted(ctx, row.did) ? { owner: row.did } : null;
}});
export const codeContext = queryGeneric({ args: { ...args, code: v.string() }, handler: async (ctx, input) => {
  auth(input.serviceSecret, input.role);
  if (!ReferralCodeSchema.safeParse(input.code).success) return null;
  const row = await ctx.db.query("referralCodes").withIndex("by_code", (q: any) => q.eq("code", input.code)).unique();
  return row && !row.revokedAt && !await accountDeleted(ctx, row.ownerDid) ? { owner: row.ownerDid, application: row.application } : null;
}});
export const catalog = queryGeneric({ args, handler: async (ctx, input) => {
  auth(input.serviceSecret, input.role);
  if (process.env.NOTORGANIC_STORAGE_BACKEND !== "unison") throw new Error("CATALOG_CUTOVER_REQUIRED");
  const definitions = await ctx.db.query("achievementDefinitions").take(501);
  const policies = await ctx.db.query("referralPolicies").take(9);
  if (definitions.length > 500 || policies.length > 8) throw new Error("CATALOG_MIGRATION_CAPACITY");
  const items = [
    ...definitions.map(row => ({ kind: "definition", application: row.application, key: row.key, title: row.title, description: row.description, assetPath: row.assetPath, reward: row.rewardMicros, active: row.active, updatedAt: row.updatedAt })),
    ...policies.map(row => ({ kind: "policy", application: row.application, event: row.qualifyingEvent, referrerReward: row.referrerRewardMicros, refereeReward: row.refereeRewardMicros, active: row.active, updatedAt: row.updatedAt })),
  ].sort((a,b) => canonical(a).localeCompare(canonical(b)));
